  line-height:1.7;
  overflow-x:hidden;
  -webkit-font-smoothing:antialiased;
}
img{ display:block; max-width:100%; }
a{ color:inherit; text-decoration:none; }
ul{ list-style:none; }
button{ font-family:inherit; cursor:pointer; border:none; background:none; color:inherit; }
::selection{ background:var(--gold); color:var(--noir); }
::-webkit-scrollbar{ width:10px; }
::-webkit-scrollbar-track{ background:var(--noir); }
::-webkit-scrollbar-thumb{ background:var(--gold-3); border-radius:6px; }

.container{ width:min(1200px,92vw); margin-inline:auto; }
.section{ padding:clamp(90px,12vh,150px) 0; position:relative; }
.section.alt{ background:var(--noir-2); }

/* Grano fílmico sutil sobre toda la página */
body::after{
  content:'';
