/* ── 11 · LÍNEA DE TIEMPO ──────────────────────────────────────────────────── */
class TimelineRenderer extends SectionRenderer {
  build() {
    const line = Dom.el('div', 'tl-line');
    this.root.appendChild(line);
    this.data.forEach((item) => {
      const node = Dom.el('div', 'tl-item');
      node.innerHTML =
        '<span class="tl-when">' + item.when + '</span>' +
        '<h4><span class="flag">' + item.flag + '</span>' + item.place + '</h4>' +
        '<p>' + item.text + '</p>';
      this.root.appendChild(node);
    });
    this.line = line;
  }
  animate() {
    gsap.from(this.line, {
      scaleY: 0, transformOrigin: 'top', ease: 'none',
      scrollTrigger: { trigger: this.root, start: 'top 80%', end: 'bottom 60%', scrub: 1 }
    });
    gsap.from(Dom.qsa('.tl-item', this.root), {
      x: -36, autoAlpha: 0, stagger: .15, duration: .9, ease: Config.EASE_SOFT,
      scrollTrigger: { trigger: this.root, start: 'top 75%' }
    });
  }
}

/* ── 12 · TÍTULOS CON TILT 3D ──────────────────────────────────────────────── */
class TitlesRenderer extends SectionRenderer {
  build() {
    this.data.forEach((t) => {
      const card = Dom.el('article', 'title-card' + (t.winner ? ' winner' : ''));
      card.innerHTML =
        '<span class="crown-ico">' + t.crown + '</span>' +
        '<span class="year">' + t.year + '</span>' +
        '<h3>' + t.name + '</h3><p>' + t.text + '</p>';
      this.root.appendChild(card);
      new TiltCard(card);
    });
  }
  animate() {
    gsap.from(Dom.qsa('.title-card', this.root), {
      y: 70, autoAlpha: 0, stagger: .12, duration: 1, ease: Config.EASE_SOFT,
      scrollTrigger: { trigger: this.root, start: 'top 80%' }
    });
  }
}
class TiltCard {
  constructor(card) {
    this.card = card;
    if (!window.matchMedia('(pointer:fine)').matches) return;
    this.rx = gsap.quickTo(card, 'rotationX', { duration: .5, ease: 'power2' });
    this.ry = gsap.quickTo(card, 'rotationY', { duration: .5, ease: 'power2' });
    card.addEventListener('mousemove', (e) => this.#move(e));
    card.addEventListener('mouseleave', () => this.#reset());
  }
  #move(e) {
    const r = this.card.getBoundingClientRect();
    const px = (e.clientX - r.left) / r.width - 0.5;
    const py = (e.clientY - r.top) / r.height - 0.5;
    this.ry(px * 10); this.rx(-py * 10);
  }
  #reset() { this.rx(0); this.ry(0); }
}

