/* ── 14 · FILMOGRAFÍA APILADA (sticky + scrub) ─────────────────────────────── */
class FilmsRenderer extends SectionRenderer {
  build() {
    this.data.forEach((f, i) => {
      const card = Dom.el('article', 'film-card');
      card.style.top = 'calc(' + (Config.NAV_OFFSET + 16) + 'px + ' + (i * 14) + 'px)';
      card.innerHTML =
        '<div class="film-visual"><img src="' + f.img + '" alt="' + f.title + '" loading="lazy">' +
        '<span class="film-year">' + f.year + '</span></div>' +
        '<div class="film-body"><span class="film-type">' + f.type + '</span>' +
        '<h3>' + f.title + '</h3><div class="film-role">' + f.role + '</div>' +
        '<p class="desc">' + f.desc + '</p>' +
        '<ul class="awards">' + f.awards.map((a) => '<li>' + a + '</li>').join('') + '</ul></div>';
      this.root.appendChild(card);
    });
  }
  animate() {
    const cards = Dom.qsa('.film-card', this.root);
    cards.forEach((card, i) => {
      if (i === 0) return;
      const prev = cards[i - 1];
      gsap.to(prev, {
        scale: .94, filter: 'brightness(.55)', ease: 'none',
        scrollTrigger: {
          trigger: card, start: 'top bottom', end: 'top top+=140', scrub: true
        }
      });
    });
  }
}

