  position:absolute; bottom:26px; left:50%;
  transform:translateX(-50%);
  font-size:.66rem; letter-spacing:.5em; color:var(--muted);
  writing-mode:vertical-rl; z-index:2;
}
.scroll-hint::after{
  content:''; display:block; width:1px; height:52px;
  margin:12px auto 0; background:var(--gold);
  animation:hint 2s var(--ease) infinite;
  transform-origin:top;
}
@keyframes hint{ 0%{transform:scaleY(0)} 45%{transform:scaleY(1)} 100%{transform:scaleY(0); transform-origin:bottom} }

/* ── 07 · MARQUESINA ───────────────────────────────────────────────────────── */
.marquee{ border-block:1px solid var(--line); background:var(--noir-2); overflow:hidden; padding:18px 0; }
.marquee-track{
  display:flex; gap:56px; width:max-content;
  font-family:var(--serif); font-weight:700;
  font-size:clamp(1rem,2.4vw,1.5rem);
  text-transform:uppercase; letter-spacing:.3em;
  color:var(--gold); white-space:nowrap;
}
.marquee-track em{ color:var(--emerald-2); font-style:normal; }

/* ── 08 · CABECERAS DE SECCIÓN ─────────────────────────────────────────────── */
.sec-head{ display:flex; align-items:baseline; gap:22px; margin-bottom:clamp(44px,7vh,80px); position:relative; }
.sec-num{
  font-family:var(--serif); font-style:italic;
  font-size:clamp(2.6rem,6vw,4.6rem);
  color:transparent; -webkit-text-stroke:1px var(--gold-3); line-height:1;
}
.sec-head h2{
  font-family:var(--serif); font-weight:700;
  font-size:clamp(2rem,5vw,3.6rem);
  text-transform:uppercase; letter-spacing:.06em;
}
.sec-tag{ margin-left:auto; font-size:.74rem; letter-spacing:.34em; text-transform:uppercase; color:var(--emerald-2); }
.sec-head::after{
  content:''; position:absolute; left:0; bottom:-18px;
  width:90px; height:2px;
  background:linear-gradient(90deg,var(--gold),transparent);
}

/* ── 09 · BIOGRAFÍA (sticky 2 columnas + línea de tiempo) ──────────────────── */
.bio-grid{ display:grid; grid-template-columns:.9fr 1.1fr; gap:clamp(36px,6vw,90px); align-items:start; }
.bio-sticky{ position:sticky; top:calc(var(--nav-h) + 30px); }
.bio-sticky .ph{
  overflow:hidden; border-radius:var(--radius);
  border:1px solid var(--line);
  box-shadow:0 24px 70px rgba(0,0,0,.5);
}
.bio-sticky img{ width:100%; }
.bio-sticky figcaption{
  padding:14px 6px 0;
  font-family:var(--serif); font-style:italic;
  color:var(--muted); font-size:1.05rem;
}
.bio-flow .lead{
  font-family:var(--serif); font-weight:500;
  font-size:clamp(1.25rem,2.6vw,1.8rem);
  line-height:1.45; color:var(--ink); margin-bottom:26px;
}
.bio-flow .lead em{ color:var(--gold-2); }
.bio-flow p.body{ color:var(--muted); max-width:58ch; margin-bottom:20px; }
.quote-block{
  border-left:2px solid var(--gold);
  padding:10px 0 10px 26px; margin:34px 0;
  font-family:var(--serif); font-style:italic;
  font-size:clamp(1.15rem,2.2vw,1.5rem);
  color:var(--blush);
}
.quote-block cite{
  display:block; margin-top:10px;
  font-family:var(--sans); font-style:normal;
  font-size:.72rem; letter-spacing:.3em;
  text-transform:uppercase; color:var(--gold);
}
.timeline{ margin-top:56px; position:relative; padding-left:34px; }
.timeline .tl-line{
  position:absolute; left:8px; top:0; bottom:0; width:1px;
  background:linear-gradient(180deg,var(--gold),var(--emerald));
  transform-origin:top;
}
.tl-item{ position:relative; padding-bottom:40px; }
.tl-item::before{
  content:''; position:absolute; left:-30px; top:8px;
  width:9px; height:9px; border-radius:50%;
  background:var(--noir); border:2px solid var(--gold);
  box-shadow:0 0 0 5px rgba(216,180,90,.12);
}
.tl-item h4{
  font-family:var(--serif); font-weight:700;
  font-size:1.35rem; color:var(--gold-2);
  display:flex; align-items:center; gap:12px;
}
.tl-item h4 .flag{ font-size:1.1rem; }
.tl-item .tl-when{ font-size:.68rem; letter-spacing:.3em; text-transform:uppercase; color:var(--emerald-2); }
.tl-item p{ color:var(--muted); max-width:52ch; margin-top:6px; }

/* ── 10 · CORONA / TÍTULOS ─────────────────────────────────────────────────── */
.titles-grid{ display:grid; grid-template-columns:repeat(auto-fit,minmax(255px,1fr)); gap:22px; }
.title-card{
  background:linear-gradient(160deg,var(--noir-3),var(--noir-2));
  border:1px solid var(--line); border-radius:var(--radius);
  padding:30px 26px; position:relative; overflow:hidden;
  transform-style:preserve-3d; will-change:transform;
  transition:border-color .4s;
}
.title-card:hover{ border-color:var(--gold-3); }
.title-card::before{ content:'✦'; position:absolute; top:18px; right:20px; color:var(--emerald-2); font-size:1rem; }
.title-card .year{ font-family:var(--serif); font-style:italic; color:var(--emerald-2); font-size:1rem; letter-spacing:.14em; }
.title-card h3{ font-family:var(--serif); font-weight:700; font-size:1.5rem; line-height:1.15; color:var(--gold-2); margin:10px 0 12px; }
.title-card p{ color:var(--muted); font-size:.92rem; }
.title-card .crown-ico{ font-size:1.6rem; margin-bottom:14px; display:block; }
.title-card.winner{ border-color:var(--gold-3); background:linear-gradient(160deg,#241a10,var(--noir-2)); }
.title-card.winner h3{ color:var(--ink); }
.supranational{ margin-top:clamp(60px,9vh,100px); }
.supranational h3{ font-family:var(--serif); font-weight:700; font-size:clamp(1.5rem,3.4vw,2.3rem); color:var(--ink); }
.supranational h3 em{ color:var(--emerald-2); font-style:italic; }
.supranational .sup-meta{ color:var(--muted); margin:8px 0 30px; font-size:.82rem; letter-spacing:.22em; text-transform:uppercase; }
.contestants{ display:grid; grid-template-columns:repeat(auto-fill,minmax(170px,1fr)); gap:12px; }
.contestant{
  border:1px solid rgba(244,236,223,.1);
  border-radius:10px; padding:14px 16px;
  display:flex; align-items:center; gap:12px;
  background:rgba(255,255,255,.02);
  transition:transform .35s var(--ease), border-color .3s, background .3s;
}
.contestant:hover{ transform:translateY(-4px); border-color:var(--line); }
.contestant .flag{ font-size:1.35rem; }
.contestant .c-country{ font-size:.66rem; letter-spacing:.24em; text-transform:uppercase; color:var(--muted); display:block; }
.contestant .c-name{ font-weight:400; font-size:.9rem; color:var(--ink); }
.contestant.winner{
  border-color:var(--gold);
  background:linear-gradient(140deg,rgba(216,180,90,.16),rgba(14,138,99,.12));
}
.contestant.winner .c-name{ color:var(--gold-2); font-weight:600; }
.contestant.winner .c-tag{
  margin-left:auto; font-size:.62rem; letter-spacing:.2em;
  color:var(--noir); background:var(--gold);
  padding:3px 8px; border-radius:999px; font-weight:600;
}

/* ── 11 · CINE & TV (tarjetas apiladas) ────────────────────────────────────── */
#films{ display:flex; flex-direction:column; gap:26px; }
.film-card{
  position:sticky;
  border-radius:var(--radius);
  border:1px solid var(--line);
  overflow:hidden;
  display:grid; grid-template-columns:1fr 1.2fr;
  min-height:380px;
  background:var(--noir-3);
  box-shadow:0 -12px 50px rgba(0,0,0,.5);
  will-change:transform;
}
.film-card .film-visual{ position:relative; overflow:hidden; min-height:260px; }
.film-card .film-visual img{ width:100%; height:100%; object-fit:cover; position:absolute; inset:0; }
.film-card .film-visual .film-year{
  position:absolute; top:18px; left:18px; z-index:2;
  background:var(--noir); border:1px solid var(--gold-3);
  color:var(--gold-2); font-family:var(--serif); font-style:italic;
  padding:6px 14px; border-radius:999px; font-size:.95rem;
}
.film-card .film-body{ padding:clamp(26px,4vw,50px); }
.film-card .film-type{ font-size:.68rem; letter-spacing:.32em; text-transform:uppercase; color:var(--emerald-2); }
.film-card h3{ font-family:var(--serif); font-weight:700; font-size:clamp(1.6rem,3.4vw,2.5rem); color:var(--ink); margin:10px 0 14px; line-height:1.1; }
.film-card .film-role{ font-family:var(--serif); font-style:italic; color:var(--gold-2); font-size:1.05rem; margin-bottom:12px; }
.film-card p.desc{ color:var(--muted); font-size:.95rem; max-width:56ch; }
.film-card ul.awards{ margin-top:18px; display:grid; gap:8px; }
.film-card ul.awards li{ font-size:.85rem; color:var(--blush); display:flex; gap:10px; align-items:baseline; }
.film-card ul.awards li::before{ content:'✦'; color:var(--gold); font-size:.7rem; }

/* ── 12 · CARRERA ──────────────────────────────────────────────────────────── */
.career-grid{ display:grid; grid-template-columns:repeat(auto-fit,minmax(270px,1fr)); gap:22px; }
.career-card{
  border:1px solid rgba(244,236,223,.1); border-radius:var(--radius);
  padding:32px 28px; background:var(--noir);
  display:flex; flex-direction:column; gap:12px;
  transition:transform .4s var(--ease), border-color .3s;
}
.career-card:hover{ transform:translateY(-6px); border-color:var(--emerald); }
.career-card .ico{
  width:52px; height:52px; border-radius:50%;
  border:1px solid var(--gold-3); color:var(--gold-2);
  display:flex; align-items:center; justify-content:center;
  font-size:1.3rem;
}
.career-card h3{ font-family:var(--serif); font-weight:700; font-size:1.45rem; color:var(--ink); }
.career-card .role{ font-size:.7rem; letter-spacing:.28em; text-transform:uppercase; color:var(--emerald-2); }
.career-card p{ color:var(--muted); font-size:.92rem; }
.career-card .mini-quote{
  margin-top:auto; padding-top:14px; border-top:1px dashed var(--line);
  font-family:var(--serif); font-style:italic; color:var(--blush); font-size:.98rem;
}

/* ── 13 · ACTIVISMO ────────────────────────────────────────────────────────── */
.act-grid{ display:grid; grid-template-columns:1fr 1fr; gap:22px; }
.act-panel{
  border-radius:var(--radius); overflow:hidden;
  border:1px solid var(--line); position:relative;
  padding:clamp(30px,4vw,52px);
  background:
    radial-gradient(120% 90% at 100% 0%, rgba(14,138,99,.18), transparent 55%),
    var(--noir-3);
}
.act-panel h3{ font-family:var(--serif); font-weight:700; font-size:clamp(1.5rem,3vw,2.1rem); color:var(--gold-2); margin-bottom:6px; }
.act-panel .act-role{ font-size:.7rem; letter-spacing:.3em; text-transform:uppercase; color:var(--emerald-2); }
.act-panel p{ color:var(--muted); margin-top:14px; font-size:.95rem; }
.act-panel ul{ margin-top:16px; display:flex; flex-wrap:wrap; gap:8px; }
.act-panel ul li{ font-size:.74rem; letter-spacing:.12em; border:1px solid var(--line); border-radius:999px; padding:6px 14px; color:var(--blush); }
.act-panel .big-quote{ margin-top:22px; font-family:var(--serif); font-style:italic; font-size:1.15rem; color:var(--ink); }

/* ── 14 · GALERÍA (parallax + lightbox) ────────────────────────────────────── */
#gallery-grid{ display:grid; grid-template-columns:repeat(6,1fr); gap:18px; }
.g-item{
  position:relative; overflow:hidden; border-radius:var(--radius);
  border:1px solid var(--line); cursor:pointer;
  background:var(--noir-2);
}
.g-item:nth-child(1){ grid-column:span 3; aspect-ratio:3/4; }
.g-item:nth-child(2){ grid-column:span 3; aspect-ratio:3/4; }
.g-item:nth-child(3){ grid-column:span 2; aspect-ratio:4/5; }
.g-item:nth-child(4){ grid-column:span 2; aspect-ratio:4/5; }
.g-item:nth-child(5){ grid-column:span 2; aspect-ratio:4/5; }
.g-item img{
  width:100%; height:120%; object-fit:cover;
  position:absolute; left:0; top:-10%;
  will-change:transform; transition:filter .5s;
}
.g-item:hover img{ filter:brightness(1.12) saturate(1.05); }
.g-item figcaption{
  position:absolute; left:0; right:0; bottom:0; z-index:2;
  padding:44px 18px 14px;
  background:linear-gradient(transparent,rgba(14,10,18,.9));
  font-family:var(--serif); font-style:italic; font-size:1rem;
  color:var(--gold-2);
}
#lightbox{
  position:fixed; inset:0; z-index:250;
  background:rgba(10,7,14,.94);
  display:flex; align-items:center; justify-content:center;
  flex-direction:column; gap:18px;
  opacity:0; pointer-events:none;
}
#lightbox.open{ pointer-events:auto; }
#lightbox img{ max-height:78vh; max-width:88vw; border-radius:10px; border:1px solid var(--gold-3); box-shadow:0 40px 120px rgba(0,0,0,.8); }
#lightbox figcaption{ font-family:var(--serif); font-style:italic; color:var(--blush); font-size:1.1rem; }
#lightbox .lb-close{ position:absolute; top:26px; right:30px; font-size:.8rem; letter-spacing:.3em; color:var(--gold-2); text-transform:uppercase; }

/* ── 15 · FRASES ROTATORIAS ────────────────────────────────────────────────── */
#quotes{ text-align:center; overflow:hidden; }
#quotes .q-mark{ font-family:var(--serif); font-size:5rem; color:var(--gold-3); line-height:.6; }
#quote-text{
  font-family:var(--serif); font-style:italic; font-weight:500;
  font-size:clamp(1.5rem,4vw,2.9rem); line-height:1.3;
  max-width:26ch; margin:26px auto;
  color:var(--ink); min-height:3.8em;
}
#quote-idx{ font-size:.74rem; letter-spacing:.4em; color:var(--emerald-2); text-transform:uppercase; }
.q-dots{ display:flex; gap:10px; justify-content:center; margin-top:26px; }
.q-dots button{ width:26px; height:2px; background:rgba(244,236,223,.2); transition:background .3s; }
.q-dots button.on{ background:var(--gold); }

/* ── 16 · GITHUB EXPORT ────────────────────────────────────────────────────── */
.gh-wrap{ display:grid; grid-template-columns:1fr 1fr; gap:30px; align-items:start; }
.gh-copy h3{ font-family:var(--serif); font-weight:700; font-size:1.8rem; color:var(--ink); }
.gh-copy p{ color:var(--muted); margin:14px 0 22px; max-width:48ch; }
.gh-actions{ display:flex; gap:14px; flex-wrap:wrap; }
.terminal{ background:#0a0d10; border:1px solid #23303a; border-radius:12px; overflow:hidden; font-family:'Courier New',monospace; font-size:.86rem; }
.terminal .t-bar{ display:flex; gap:7px; align-items:center; padding:12px 16px; background:#10171c; border-bottom:1px solid #23303a; }
.terminal .t-bar i{ width:11px; height:11px; border-radius:50%; }
.terminal .t-bar i:nth-child(1){ background:#ff5f57; }
.terminal .t-bar i:nth-child(2){ background:#febc2e; }
.terminal .t-bar i:nth-child(3){ background:#28c840; }
.terminal .t-bar span{ margin-left:auto; color:#5b6b76; font-size:.72rem; letter-spacing:.12em; }
.terminal pre{ padding:20px 22px; overflow-x:auto; line-height:1.9; }
.terminal .cm{ color:#5b6b76; }
.terminal .cmd{ color:#7ee787; }
.terminal .cmd::before{ content:'$ '; color:#58a6ff; }

/* ── 17 · FOOTER ───────────────────────────────────────────────────────────── */
footer{ border-top:1px solid var(--line); padding:56px 0 40px; background:var(--noir); }
.foot-grid{ display:flex; justify-content:space-between; gap:30px; flex-wrap:wrap; align-items:flex-start; }
.foot-brand{ font-family:var(--serif); font-weight:700; font-size:1.6rem; color:var(--gold-2); letter-spacing:.2em; }
.foot-brand small{ display:block; font-family:var(--sans); font-weight:400; font-size:.7rem; letter-spacing:.34em; color:var(--muted); margin-top:6px; text-transform:uppercase; }
.foot-social{ display:flex; gap:12px; flex-wrap:wrap; }
.foot-social a{
  border:1px solid var(--line); border-radius:999px;
  padding:9px 20px; font-size:.74rem; letter-spacing:.22em;
  text-transform:uppercase; color:var(--muted); transition:all .3s;
}
.foot-social a:hover{ border-color:var(--gold); color:var(--gold-2); }
.foot-base{
  margin-top:40px; padding-top:22px; border-top:1px dashed rgba(244,236,223,.1);
  display:flex; justify-content:space-between; gap:16px; flex-wrap:wrap;
  font-size:.72rem; letter-spacing:.18em; color:var(--muted); text-transform:uppercase;
}
.foot-base em{ color:var(--emerald-2); font-style:normal; }

/* ── 18 · UTILIDADES REVEAL ────────────────────────────────────────────────── */
[data-reveal]{ opacity:0; transform:translateY(46px); }
[data-reveal].in{ opacity:1; transform:none; transition:opacity .9s var(--ease),transform .9s var(--ease); }

/* ── 19 · RESPONSIVE ───────────────────────────────────────────────────────── */
@media (max-width:1020px){
  .hero-inner{ grid-template-columns:1fr; text-align:left; }
  .hero-portrait{ width:min(360px,72%); margin-top:10px; }
  .bio-grid{ grid-template-columns:1fr; }
  .bio-sticky{ position:relative; top:0; max-width:440px; }
  .act-grid,.gh-wrap{ grid-template-columns:1fr; }
  .film-card{ grid-template-columns:1fr; }
  .film-card .film-visual{ min-height:230px; }
}
@media (max-width:820px){
  #menu-btn{ display:flex; }
  #nav ul{
    position:fixed; inset:0; z-index:115;
    background:rgba(14,10,18,.97);
    flex-direction:column; justify-content:center; gap:26px;
    transform:translateX(100%); transition:transform .55s var(--ease);
  }
  #nav ul.open{ transform:translateX(0); }
  #nav ul a{ font-size:1rem; }
  #gallery-grid{ grid-template-columns:1fr 1fr; }
  .g-item{ grid-column:span 1 !important; aspect-ratio:3/4 !important; }
  .sec-tag{ display:none; }
}
@media (max-width:560px){
  #gallery-grid{ grid-template-columns:1fr; }
  .hero-meta .stat{ border:none; padding-left:0; }
}
</style>
</head>

