<!-- ═══ MARQUESINA ═══ -->
<div class="marquee" aria-hidden="true"><div class="marquee-track" id="marquee-track"></div></div>

<!-- ═══ 01 · BIOGRAFÍA ═══ -->
<section id="bio" class="section">
  <div class="container">
    <header class="sec-head">
