/* ── 03 · UTILIDADES DOM ───────────────────────────────────────────────────── */
class Dom {
  static el(tag, cls, html) {
    const node = document.createElement(tag);
    if (cls) node.className = cls;
    if (html !== undefined) node.innerHTML = html;
    return node;
  }
  static qs(sel, root) { return (root || document).querySelector(sel); }
  static qsa(sel, root) { return Array.from((root || document).querySelectorAll(sel)); }
}

/* ── 04 · DIVISOR DE TEXTO (chars para el hero) ────────────────────────────── */
class TextSplitter {
  constructor(element) {
    this.element = element;
    this.chars = [];
    this.#split();
  }
  #split() {
    const raw = this.element.textContent.trim();
    this.element.setAttribute('aria-label', raw);
    this.element.textContent = '';
    const words = raw.split(' ');
    words.forEach((word, wIdx) => {
      const wrap = Dom.el('span', 'word');
      wrap.style.display = 'inline-block';
      wrap.style.whiteSpace = 'nowrap';
      Array.from(word).forEach((ch) => {
        const s = Dom.el('span', 'ch');
        if (wIdx === 1) s.classList.add('gold');
        s.textContent = ch;
        wrap.appendChild(s);
        this.chars.push(s);
      });
      this.element.appendChild(wrap);
      if (wIdx < words.length - 1) this.element.appendChild(document.createTextNode(' '));
    });
  }
}

/* ── 05 · PRELOADER (corona dibujada + contador) ───────────────────────────── */
class Preloader {
  constructor(onComplete) {
    this.onComplete = onComplete;
    this.root  = Dom.qs('#preloader');
    this.fill  = Dom.qs('#load-fill');
    this.count = Dom.qs('#load-count');
  }
  run() {
    const path = Dom.qs('#crown-path');
    const len  = path.getTotalLength();
    gsap.set(path, { strokeDasharray: len, strokeDashoffset: len });
    const state = { n: 0 };
    gsap.timeline({ onComplete: () => this.#exit() })
      .to(path, { strokeDashoffset: 0, duration: 1.1, ease: 'power2.inOut' })
      .to(state, {
        n: 100, duration: 1.4, ease: 'power2.inOut',
        onUpdate: () => {
          this.count.textContent = Math.round(state.n) + '%';
          this.fill.style.transform = 'scaleX(' + (state.n / 100) + ')';
        }
      }, 0.2);
  }
  #exit() {
    gsap.to(this.root, {
      yPercent: -100, duration: 0.9, ease: Config.EASE_IO,
      onComplete: () => { this.root.style.display = 'none'; this.onComplete(); }
    });
  }
}

/* ── 06 · CURSOR CON INERCIA ───────────────────────────────────────────────── */
class CursorFX {
  constructor() {
    this.dot  = Dom.qs('.cursor-dot');
    this.ring = Dom.qs('.cursor-ring');
    if (!window.matchMedia('(pointer:fine)').matches) return;
    this.#bind();
  }
  #bind() {
    const dx = gsap.quickTo(this.dot,  'x', { duration: 0.12, ease: 'power2' });
    const dy = gsap.quickTo(this.dot,  'y', { duration: 0.12, ease: 'power2' });
    const rx = gsap.quickTo(this.ring, 'x', { duration: 0.45, ease: 'power3' });
    const ry = gsap.quickTo(this.ring, 'y', { duration: 0.45, ease: 'power3' });
    window.addEventListener('mousemove', (e) => { dx(e.clientX); dy(e.clientY); rx(e.clientX); ry(e.clientY); });
    document.addEventListener('mouseover', (e) => {
      const hot = e.target.closest('a,button,.g-item,.title-card,.contestant');
      this.ring.classList.toggle('is-hover', !!hot);
    });
    gsap.set([this.dot, this.ring], { xPercent: -50, yPercent: -50 });
  }
}

/* ── 07 · NAVEGACIÓN (scroll suave + estado activo + menú móvil) ───────────── */
class Navigation {
  constructor() {
    this.header  = Dom.qs('#nav');
    this.links   = Dom.qsa('[data-scroll]');
    this.menuBtn = Dom.qs('#menu-btn');
    this.list    = Dom.qs('#nav-list');
  }
  init() {
    this.links.forEach((link) => {
      link.addEventListener('click', (e) => {
        e.preventDefault();
        const target = link.getAttribute('data-scroll');
        gsap.to(window, { duration: 1.25, ease: Config.EASE_IO, scrollTo: { y: target, offsetY: Config.NAV_OFFSET } });
        this.#closeMenu();
      });
    });
    this.menuBtn.addEventListener('click', () => this.#toggleMenu());
    ScrollTrigger.create({
      start: 40,
      onUpdate: (self) => this.header.classList.toggle('is-scrolled', self.scroll() > 40)
    });
    Dom.qsa('#nav-list a').forEach((a) => {
      ScrollTrigger.create({
        trigger: a.getAttribute('data-scroll'),
        start: 'top 55%', end: 'bottom 45%',
        onToggle: (self) => a.classList.toggle('is-active', self.isActive)
      });
    });
  }
  #toggleMenu() {
    const open = this.list.classList.toggle('open');
    this.menuBtn.classList.toggle('open', open);
  }
  #closeMenu() {
    this.list.classList.remove('open');
    this.menuBtn.classList.remove('open');
  }
}

/* ── 08 · SECUENCIA HERO ───────────────────────────────────────────────────── */
class HeroSequence {
  constructor() { this.splitter = new TextSplitter(Dom.qs('#hero-title')); }
  setImage() {
    Dom.qs('#hero-bg').style.backgroundImage = 'url(' + Config.ASSETS.heroBg + ')';
    Dom.qs('#hero-img').src = Config.ASSETS.heroPortrait;
    Dom.qs('#bio-img').src  = Config.ASSETS.gold;
  }
  play() {
    gsap.timeline({ defaults: { ease: Config.EASE_OUT } })
      .from('#hero-kicker', { y: 30, autoAlpha: 0, duration: .8 })
      .from(this.splitter.chars, { yPercent: 120, rotation: 10, autoAlpha: 0, duration: 1.1, stagger: 0.028, ease: 'power4.out' }, '-=0.4')
      .from('#hero-sub', { y: 34, autoAlpha: 0, duration: .9 }, '-=0.6')
      .from('#hero-meta .stat', { y: 26, autoAlpha: 0, stagger: .1, duration: .7 }, '-=0.5')
      .from('.hero-ctas .btn', { y: 20, autoAlpha: 0, stagger: .12, duration: .6 }, '-=0.4')
      .from('#hero-portrait .frame', { clipPath: 'inset(100% 0 0 0)', duration: 1.2, ease: 'power4.inOut' }, '-=1.1')
      .to('#hero-img', { scale: 1, duration: 1.8, ease: Config.EASE_OUT }, '<')
