/* ── 12 · TÍTULOS CON TILT 3D ──────────────────────────────────────────────── */
class TiltCard {
  constructor(card) {
    this.card = card;
    if (!window.gsap) return;
    if (!window.matchMedia('(pointer:fine)').matches) return;
    this.rx = gsap.quickTo(card, 'rotationX', { duration: .5, ease: 'power2' });
    this.ry = gsap.quickTo(card, 'rotationY', { duration: .5, ease: 'power2' });
    card.addEventListener('mousemove', (e) => this.#move(e));
    card.addEventListener('mouseleave', () => this.#reset());
  }
  #move(e) {
    const r  = this.card.getBoundingClientRect();
    const px = (e.clientX - r.left) / r.width  - 0.5;
    const py = (e.clientY - r.top)  / r.height - 0.5;
    this.ry(px * 10); this.rx(-py * 10);
  }
  #reset() { this.rx(0); this.ry(0); }
}
