      '- Corona: Miss T Supranational 2024, Miss Trans Star Spain 2019, Miss Congeniality',
      '- Cine & TV: Heels Over Wheels (2022), La Casa de las Reinas (2023), Nocturnas (2023)',
      '- Carrera: Axel Hotels, Miau Events (CEO), Proescenic Talent Agency',
      '- Activismo: Stop Sida, Pride Barcelona 2025 (Master of Ceremony)',
      '- Galería con lightbox y frases rotatorias',
      '',
      '## Deploy (GitHub Pages)',
      '    git init',
      '    git add index.html',
      '    git commit -m "feat: web oficial Michelle Relayze"',
      '    git branch -M main',
      '    git remote add origin <URL_DEL_REPOSITORIO>',
      '    git push -u origin main',
      '',
      'Luego: Settings → Pages → Branch: main → Save.',
      '',
      '© ' + new Date().getFullYear() + ' · Beauty is seen, energy is felt.'
    ].join('\n');
    const blob = new Blob([readme], { type: 'text/markdown;charset=utf-8' });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    a.href = url;
    a.download = 'README.md';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 500);
    this.#flash('✓ README descargado');
  }
}

/* ── 20 · REVEALS GENÉRICOS + PROGRESO ─────────────────────────────────────── */
class RevealManager {
  init() {
    Dom.qsa('[data-reveal]').forEach((el) => {
      if (!window.gsap) { el.classList.add('in'); return; }
      ScrollTrigger.create({
        trigger: el, start: 'top 88%', once: true,
        onEnter: () => el.classList.add('in')
      });
    });
    if (!window.gsap) return;
    gsap.to('#progress', {
      scaleX: 1, ease: 'none',
      scrollTrigger: { start: 0, end: 'max', scrub: .3 }
    });
  }
}

/* ── 21 · APLICACIÓN (raíz de composición) ─────────────────────────────────── */
class App {
  constructor() {
    this.lightbox  = new Lightbox();
    this.renderers = [
      new TimelineRenderer('#timeline',       DataRepository.timeline),
      new TitlesRenderer('#titles-grid',      DataRepository.titles),
      new ContestantsRenderer('#contestants', DataRepository.contestants),
      new FilmsRenderer('#films',             DataRepository.films),
      new CareerRenderer('#career-grid',      DataRepository.career),
      new ActivismRenderer('#act-grid',       DataRepository.activism),
      new GalleryRenderer('#gallery-grid',    DataRepository.gallery, this.lightbox)
    ];
    this.hero     = new HeroSequence();
    this.marquee  = new Marquee();
    this.nav      = new Navigation();
    this.cursor   = new CursorFX();
    this.quotes   = new QuotesRotator();
    this.exporter = new GitHubExporter();
    this.reveal   = new RevealManager();
  }
  boot() {
    Dom.qs('#footer-year').textContent = new Date().getFullYear();
    this.hero.setImage();
    this.renderers.forEach((r) => r.build());
    this.marquee.init();
    this.nav.init();
    this.exporter.init();
    new Preloader(() => {
      this.hero.play();
      this.reveal.init();
      this.renderers.forEach((r) => r.animate());
      this.quotes.init();
      if (window.gsap) ScrollTrigger.refresh();
    }).run();
    window.addEventListener('load', () => {
      if (window.gsap) ScrollTrigger.refresh();
    });
  }
}

/* ── ARRANQUE ──────────────────────────────────────────────────────────────── */
window.addEventListener('DOMContentLoaded', () => new App().boot());
</script>
</body>
</html>
