        /**
         * CLASE BASE: PERSONA
         * Principio: Abstracción e Herencia.
         */
        class Persona {
            constructor(nombre, origen, profesion) {
                this.nombre = nombre;
                this.origen = origen;
                this.profesion = profesion;
            }
            obtenerResumen() {
                return `${this.nombre} es ${this.profesion} originaria de ${this.origen}.`;
            }
        }

        /**
         * CLASE DERIVADA: FIGURA PUBLICA
         * Principio: Herencia y Polimorfismo.
         */
        class FiguraPublica extends Persona {
            constructor(nombre, origen, profesion, redes) {
                super(nombre, origen, profesion);
                this.redes = redes;
            }
            obtenerResumen() {
                return `${super.obtenerResumen()} Conecta con ella en: ${this.redes.instagram}.`;
            }
        }

        /**
         * CLASE ESPECÍFICA: MICHELLE RELAYZE
         * Principio: Encapsulamiento (campos privados #) y validación.
         */
        class MichelleRelayze extends FiguraPublica {
            #tituloActual;
            #empresa;

            constructor() {
                const data = DataRepository.getProfile();
                super(data.name, data.origin, data.profession, data.social);
                this.#tituloActual = "Miss T Supranational 2024";
                this.#empresa = "Miau Events";
                this.skills = data.skills;
                this.agency = data.agency;
            }

            get tituloActual() { return this.#tituloActual; }
            set tituloActual(nuevo) { this.#tituloActual = nuevo; }

            generarBiografia() {
                return `Nacida en Lima, Perú, y residente en Barcelona, España, con proyección en São Paulo, Brasil. Representada por Proescenic Talent Agency. Pionera en la lucha por la visibilidad del colectivo trans a través de la moda, la cultura y el emprendimiento.`;
            }
        }

        /**
         * GESTOR DE INTERFAZ DE USUARIO (UI)
         * Principio: Responsabilidad Única (SRP). Maneja solo la manipulación del DOM.
         */
        class UIManager {
            constructor() {
                this.michelle = new MichelleRelayze();
                this.theme = localStorage.getItem('theme') || 'light';
            }

            init() {
                this.applyTheme();
                this.renderHeader();
                this.renderBiography();
                this.renderCards('titles-content', DataRepository.getTitles(), this.createTitleCard);
                this.renderCards('projects-content', DataRepository.getProjects(), this.createProjectCard);
                this.renderCards('activism-content', DataRepository.getActivism(), this.createActivismCard);
                this.renderFooter();
                this.setupEventListeners();
            }

            applyTheme() {
                document.documentElement.setAttribute('data-theme', this.theme);
            }

            toggleTheme() {
                this.theme = this.theme === 'light' ? 'dark' : 'light';
                localStorage.setItem('theme', this.theme);
                this.applyTheme();
            }

            renderHeader() {
                document.getElementById('hero-title').textContent = this.michelle.nombre;
                document.getElementById('hero-subtitle').textContent = this.michelle.obtenerResumen();
            }

            renderBiography() {
                const container = document.getElementById('bio-content');
                container.innerHTML = `
                    <div class="card">
                        <h3>Origen y Residencia</h3>
                        <p>${this.michelle.generarBiografia()}</p>
                    </div>
                    <div class="card">
                        <h3>Habilidades Profesionales</h3>
                        <div>${this.michelle.skills.map(s => `<span class="tag">${s}</span>`).join('')}</div>
                        <p style="margin-top:1rem"><strong>Agencia:</strong> ${this.michelle.agency}</p>
                    </div>
                    <div class="card">
                        <h3>Presencia Digital</h3>
