                        <p><strong>LinkedIn:</strong> ${this.michelle.redes.linkedin}</p>
                        <p><strong>The Handbook:</strong> ${this.michelle.redes.handbook}</p>
                    </div>
                `;
            }

            renderCards(containerId, data, cardBuilderFn) {
                const container = document.getElementById(containerId);
                container.innerHTML = data.map(item => cardBuilderFn(item)).join('');
            }

            createTitleCard(item) {
                return `
                    <div class="card">
                        <h3>${item.title} <span style="float:right; color:var(--color-text-muted)">[${item.year}]</span></h3>
                        <p><strong>Ubicación:</strong> ${item.location}</p>
