            renderFooter() {
                document.getElementById('footer-text').textContent = `© ${new Date().getFullYear()} ${this.michelle.nombre}. Todos los derechos reservados. | ${this.michelle.tituloActual}`;
            }

            setupEventListeners() {
                document.getElementById('themeToggle').addEventListener('click', () => this.toggleTheme());

                document.getElementById('copyGitBtn').addEventListener('click', () => {
                    const text = document.getElementById('github-instructions').innerText;
                    navigator.clipboard.writeText(text).then(() => {
                        alert('¡Instrucciones copiadas al portapapeles! Abre tu terminal y pégalas.');
                    });
                });
            }
        }

