    Dom.qs('#footer-year').textContent = new Date().getFullYear();
    this.hero.setImage();
    this.marquee.init();
    this.renderers.forEach((r) => r.build());
    this.nav.init();
    this.exporter.init();
    this.quotes.init();
    new Preloader(() => {
      this.hero.play();
      this.reveals.init();
      this.renderers.forEach((r) => r.animate());
      setTimeout(() => ScrollTrigger.refresh(), 350);
    }).run();
  }
}

/* ── ARRANQUE ──────────────────────────────────────────────────────────────── */
window.addEventListener('DOMContentLoaded', () => {
  const app = new App();
  app.boot();
});
</script>
</body>
