.film-card ul.awards{ margin-top:18px; display:grid; gap:8px; }
.film-card ul.awards li{ font-size:.85rem; color:var(--blush); display:flex; gap:10px; align-items:baseline; }
.film-card ul.awards li::before{ content:'✦'; color:var(--gold); font-size:.7rem; }

/* ── 12 · CARRERA ──────────────────────────────────────────────────────────── */
.career-grid{ display:grid; grid-template-columns:repeat(auto-fit,minmax(270px,1fr)); gap:22px; }
.career-card{
  border:1px solid rgba(244,236,223,.1); border-radius:var(--radius);
  padding:32px 28px; background:var(--noir);
  display:flex; flex-direction:column; gap:12px;
  transition:transform .4s var(--ease), border-color .3s;
}
.career-card:hover{ transform:translateY(-6px); border-color:var(--emerald); }
.career-card .ico{
  width:52px; height:52px; border-radius:50%;
  border:1px solid var(--gold-3); color:var(--gold-2);
  display:flex; align-items:center; justify-content:center;
  font-size:1.3rem;
}
.career-card h3{ font-family:var(--serif); font-weight:700; font-size:1.45rem; color:var(--ink); }
.career-card .role{ font-size:.7rem; letter-spacing:.28em; text-transform:uppercase; color:var(--emerald-2); }
.career-card p{ color:var(--muted); font-size:.92rem; }
.career-card .mini-quote{
  margin-top:auto; padding-top:14px; border-top:1px dashed var(--line);
  font-family:var(--serif); font-style:italic; color:var(--blush); font-size:.98rem;
}

/* ── 13 · ACTIVISMO ────────────────────────────────────────────────────────── */
.act-grid{ display:grid; grid-template-columns:1fr 1fr; gap:22px; }
.act-panel{
  border-radius:var(--radius); overflow:hidden;
  border:1px solid var(--line); position:relative;
  padding:clamp(30px,4vw,52px);
  background:
    radial-gradient(120% 90% at 100% 0%, rgba(14,138,99,.18), transparent 55%),
    var(--noir-3);
}
.act-panel h3{ font-family:var(--serif); font-weight:700; font-size:clamp(1.5rem,3vw,2.1rem); color:var(--gold-2); margin-bottom:6px; }
.act-panel .act-role{ font-size:.7rem; letter-spacing:.3em; text-transform:uppercase; color:var(--emerald-2); }
.act-panel p{ color:var(--muted); margin-top:14px; font-size:.95rem; }
.act-panel ul{ margin-top:16px; display:flex; flex-wrap:wrap; gap:8px; }
.act-panel ul li{ font-size:.74rem; letter-spacing:.12em; border:1px solid var(--line); border-radius:999px; padding:6px 14px; color:var(--blush); }
.act-panel .big-quote{ margin-top:22px; font-family:var(--serif); font-style:italic; font-size:1.15rem; color:var(--ink); }

/* ── 14 · GALERÍA (parallax + lightbox) ────────────────────────────────────── */
#gallery-grid{ display:grid; grid-template-columns:repeat(6,1fr); gap:18px; }
.g-item{
  position:relative; overflow:hidden; border-radius:var(--radius);
  border:1px solid var(--line); cursor:pointer;
  background:var(--noir-2);
}
.g-item:nth-child(1){ grid-column:span 3; aspect-ratio:3/4; }
.g-item:nth-child(2){ grid-column:span 3; aspect-ratio:3/4; }
.g-item:nth-child(3){ grid-column:span 2; aspect-ratio:4/5; }
.g-item:nth-child(4){ grid-column:span 2; aspect-ratio:4/5; }
.g-item:nth-child(5){ grid-column:span 2; aspect-ratio:4/5; }
.g-item img{
  width:100%; height:120%; object-fit:cover;
  position:absolute; left:0; top:-10%;
  will-change:transform; transition:filter .5s;
}
.g-item:hover img{ filter:brightness(1.12) saturate(1.05); }
.g-item figcaption{
  position:absolute; left:0; right:0; bottom:0; z-index:2;
  padding:44px 18px 14px;
  background:linear-gradient(transparent,rgba(14,10,18,.9));
  font-family:var(--serif); font-style:italic; font-size:1rem;
  color:var(--gold-2);
}
#lightbox{
  position:fixed; inset:0; z-index:250;
  background:rgba(10,7,14,.94);
  display:flex; align-items:center; justify-content:center;
  flex-direction:column; gap:18px;
  opacity:0; pointer-events:none;
}
#lightbox.open{ pointer-events:auto; }
#lightbox img{ max-height:78vh; max-width:88vw; border-radius:10px; border:1px solid var(--gold-3); box-shadow:0 40px 120px rgba(0,0,0,.8); }
#lightbox figcaption{ font-family:var(--serif); font-style:italic; color:var(--blush); font-size:1.1rem; }
#lightbox .lb-close{ position:absolute; top:26px; right:30px; font-size:.8rem; letter-spacing:.3em; color:var(--gold-2); text-transform:uppercase; }

/* ── 15 · FRASES ROTATORIAS ────────────────────────────────────────────────── */
#quotes{ text-align:center; overflow:hidden; }
