<script>
/* ════════════════════════════════════════════════════════════════════════════
   MICHELLE RELAYZE — APLICACIÓN WEB ORIENTADA A OBJETOS
   ────────────────────────────────────────────────────────────────────────────
   Principios OOP aplicados de forma explícita:
   · ENCAPSULAMIENTO  → campos privados (#), getters/setters, módulos cerrados.
   · HERENCIA         → SectionRenderer base → renderizadores especializados.
   · POLIMORFISMO     → cada renderizador sobrescribe build() y animate().
   · ABSTRACCIÓN      → App orquesta sin conocer detalles internos de cada capa.
   · COMPOSICIÓN      → App posee instancias (cursor, nav, galería, exporter…).
   ════════════════════════════════════════════════════════════════════════════ */
'use strict';
gsap.registerPlugin(ScrollTrigger, ScrollToPlugin);

/* ── 01 · CONFIGURACIÓN GLOBAL ─────────────────────────────────────────────── */
class Config {
  static get EASE_OUT()   { return 'power4.out'; }
  static get EASE_IO()    { return 'power3.inOut'; }
  static get EASE_SOFT()  { return 'power3.out'; }
  static get NAV_OFFSET() { return 84; }
  static get ASSETS() {
    return {
      heroBg:      'https://image.qwenlm.ai/public_source/5f8b1c2e-6be7-4d37-88d1-3a4b5f6e5e2b/19e2c7b56-b81d-405d-b706-2430623130f1.png',
      heroPortrait:'https://image.qwenlm.ai/public_source/5f8b1c2e-6be7-4d37-88d1-3a4b5f6e5e2b/158e29bfe-b08d-4f2b-807b-d1c118c420f7.png',
      gold:        'https://image.qwenlm.ai/public_source/5f8b1c2e-6be7-4d37-88d1-3a4b5f6e5e2b/1421290e4-a650-4215-a13d-51c42118f65b.png',
      sash:        'https://image.qwenlm.ai/public_source/5f8b1c2e-6be7-4d37-88d1-3a4b5f6e5e2b/16b077396-877c-40a3-a15d-f0d3180411c1.png',
      showgirl:    'https://image.qwenlm.ai/public_source/5f8b1c2e-6be7-4d37-88d1-3a4b5f6e5e2b/13546e009-64e6-414d-a4dd-7159d8319f1f.png'
    };
  }
}

