/* ── 17 · GALERÍA + LIGHTBOX ───────────────────────────────────────────────── */
class Lightbox {
  constructor() {
    this.root = Dom.qs('#lightbox');
    this.img  = Dom.qs('#lb-img');
    this.cap  = Dom.qs('#lb-cap');
    Dom.qs('#lb-close').addEventListener('click', () => this.close());
    this.root.addEventListener('click', (e) => { if (e.target === this.root) this.close(); });
    document.addEventListener('keydown', (e) => { if (e.key === 'Escape') this.close(); });
  }
  open(src, cap) {
    this.img.src = src; this.cap.textContent = cap;
    this.root.classList.add('open');
    gsap.fromTo(this.root, { opacity: 0 }, { opacity: 1, duration: .4 });
    gsap.fromTo(this.img, { scale: .92 }, { scale: 1, duration: .6, ease: Config.EASE_OUT });
  }
  close() {
    gsap.to(this.root, { opacity: 0, duration: .35, onComplete: () => this.root.classList.remove('open') });
  }
}
class GalleryRenderer extends SectionRenderer {
  constructor(rootSelector, data, lightbox) {
    super(rootSelector, data);
    this.lightbox = lightbox;
  }
  build() {
    this.data.forEach((g) => {
      const fig = Dom.el('figure', 'g-item');
      fig.innerHTML = '<img src="' + g.src + '" alt="' + g.cap + '" loading="lazy">' +
                      '<figcaption>' + g.cap + '</figcaption>';
      fig.addEventListener('click', () => this.lightbox.open(g.src, g.cap));
      this.root.appendChild(fig);
    });
  }
  animate() {
    Dom.qsa('.g-item', this.root).forEach((item) => {
      const img = Dom.qs('img', item);
      gsap.fromTo(img, { yPercent: -8 }, { yPercent: 8, ease: 'none',
        scrollTrigger: { trigger: item, start: 'top bottom', end: 'bottom top', scrub: 1 } });
      gsap.from(item, { autoAlpha: 0, y: 50, duration: 1, ease: Config.EASE_SOFT,
        scrollTrigger: { trigger: item, start: 'top 88%' } });
    });
  }
}

/* ── 18 · ROTADOR DE FRASES ────────────────────────────────────────────────── */
class QuotesRotator {
  constructor() {
    this.quotes = DataRepository.quotes;
    this.textEl = Dom.qs('#quote-text');
    this.idxEl  = Dom.qs('#quote-idx');
    this.dotsEl = Dom.qs('#q-dots');
    this.current = 0;
    this.timer = null;
  }
  init() {
    this.quotes.forEach((_, i) => {
      const dot = Dom.el('button', i === 0 ? 'on' : '');
      dot.setAttribute('aria-label', 'Frase ' + (i + 1));
      dot.addEventListener('click', () => { this.show(i); this.restart(); });
      this.dotsEl.appendChild(dot);
    });
    this.show(0);
    this.restart();
    ScrollTrigger.create({ trigger: '#quotes', start: 'top 70%',
      onEnter: () => this.restart(), onLeaveBack: () => this.stop() });
  }
  show(i) {
    this.current = i;
    gsap.timeline()
      .to(this.textEl, { y: -24, autoAlpha: 0, duration: .45, ease: 'power2.in' })
      .add(() => {
        this.textEl.textContent = '«' + this.quotes[i] + '»';
        this.idxEl.textContent = (i + 1) + ' / ' + this.quotes.length + ' — Michelle Relayze';
        Dom.qsa('button', this.dotsEl).forEach((d, k) => d.classList.toggle('on', k === i));
      })
      .fromTo(this.textEl, { y: 30, autoAlpha: 0 }, { y: 0, autoAlpha: 1, duration: .7, ease: Config.EASE_OUT });
  }
  restart() {
    this.stop();
    this.timer = setInterval(() => this.show((this.current + 1) % this.quotes.length), 5200);
  }
  stop() { if (this.timer) clearInterval(this.timer); }
}

/* ── 19 · REVEAL GENÉRICO + PROGRESO ───────────────────────────────────────── */
class RevealManager {
  init() {
    Dom.qsa('[data-reveal]').forEach((el) => {
      ScrollTrigger.create({ trigger: el, start: 'top 88%', once: true,
        onEnter: () => el.classList.add('in') });
    });
    gsap.to('#progress', { scaleX: 1, ease: 'none',
      scrollTrigger: { start: 0, end: 'max', scrub: .3 } });
  }
}

/* ── 20 · EXPORTADOR A GITHUB ──────────────────────────────────────────────── */
class GitHubExporter {
  static get commands() {
    return [
      { cm: '# 1 · Inicializa el repositorio local' },
      { cmd: 'git init' },
      { cmd: 'git add index.html' },
      { cmd: 'git commit -m "feat: Michelle Relayze — web oficial GSAP + OOP"' },
      { cm: '# 2 · Conecta tu repositorio remoto' },
      { cmd: 'git branch -M main' },
      { cmd: 'git remote add origin https://github.com/TU_USUARIO/michelle-relayze-web.git' },
      { cm: '# 3 · Publica' },
      { cmd: 'git push -u origin main' },
      { cm: '# 4 · GitHub Pages → Settings > Pages > Branch: main > Save' }
    ];
  }
  constructor() { this.term = Dom.qs('#term-lines'); }
  init() {
    this.term.innerHTML = GitHubExporter.commands.map((l) =>
      l.cm ? '<span class="cm">' + l.cm + '</span>' : '<span class="cmd">' + l.cmd + '</span>'
    ).join('\n');
    Dom.qs('#copy-cmds').addEventListener('click', () => this.#copy());
    Dom.qs('#dl-readme').addEventListener('click', () => this.#download());
  }
  #copy() {
    const raw = GitHubExporter.commands.map((l) => l.cm || l.cmd).join('\n');
    navigator.clipboard.writeText(raw).then(() => this.#flash('✓ Copiado'));
  }
  #flash(msg) {
    const btn = Dom.qs('#copy-cmds');
    const old = btn.textContent;
    btn.textContent = msg;
    setTimeout(() => { btn.textContent = old; }, 1600);
  }
  #download() {
    const readme = [
      '# Michelle Relayze — Web Oficial ✦', '',
      'Sitio oficial de **Michelle Relayze**, primera **Miss T Supranational 2024**.',
      'Construido con HTML5 + CSS3 + **GSAP (ScrollTrigger)** y arquitectura **OOP** en JavaScript.', '',
      '## Secciones',
      '- Biografía y línea de tiempo (Lima → Uruguay → Florencia → Barcelona → São Paulo)',
      '- Corona: Miss T Supranational 2024, Miss Trans Star Spain 2019, Miss Congeniality',
      '- Cine & TV: Heels Over Wheels (2022), La Casa de las Reinas (2023), Nocturnas (2023)',
      '- Carrera: Axel Hotels, Miau Events (CEO), Proescenic Talent Agency',
      '- Activismo: Stop Sida, Pride Barcelona 2025 (Master of Ceremony)',
      '- Galería con lightbox y frases rotatorias', '',
      '## Deploy',
      '```bash', 'git init && git add . && git commit -m "init"',
      'git branch -M main', 'git remote add origin <URL>', 'git push -u origin main', '```',
      'Activa **GitHub Pages** en Settings → Pages → branch `main`.', '',
      '© ' + new Date().getFullYear() + ' · Beauty is seen, energy is felt.'
    ].join('\n');
    const blob = new Blob([readme], { type: 'text/markdown;charset=utf-8' });
    const url  = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'README.md';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 500);
    this.#flash('✓ README descargado');
  }
}

/* ── 21 · APLICACIÓN (raíz de composición) ─────────────────────────────────── */
class App {
  constructor() {
    this.lightbox = new Lightbox();
    this.renderers = [
      new TimelineRenderer('#timeline',     DataRepository.timeline),
      new TitlesRenderer('#titles-grid',    DataRepository.titles),
      new ContestantsRenderer('#contestants', DataRepository.contestants),
      new FilmsRenderer('#films',           DataRepository.films),
      new CareerRenderer('#career-grid',    DataRepository.career),
      new ActivismRenderer('#act-grid',     DataRepository.activism),
      new GalleryRenderer('#gallery-grid',  DataRepository.gallery, this.lightbox)
    ];
    this.hero     = new HeroSequence();
    this.marquee  = new Marquee();
    this.nav      = new Navigation();
    this.cursor   = new CursorFX();
    this.quotes   = new QuotesRotator();
    this.exporter = new GitHubExporter();
    this.reveal   = new RevealManager();
  }
  boot() {
    this.hero.setImage();
    this.renderers.forEach((r) => r.build());
    this.marquee.init();
    this.nav.init();
    this.exporter.init();
    Dom.qs('#footer-year').textContent = new Date().getFullYear();
    new Preloader(() => {
      this.hero.play();
      this.reveal.init();
      this.renderers.forEach((r) => r.animate());
      this.quotes.init();
      ScrollTrigger.refresh();
    }).run();
    window.addEventListener('load', () => ScrollTrigger.refresh());
  }
}
window.addEventListener('DOMContentLoaded', () => new App().boot());
</script>
</body>
</html>
