}

/* ── 18 · ROTADOR DE FRASES ────────────────────────────────────────────────── */
class QuotesRotator {
  constructor() {
    this.quotes = DataRepository.quotes;
    this.textEl = Dom.qs('#quote-text');
    this.idxEl  = Dom.qs('#quote-idx');
    this.dotsEl = Dom.qs('#q-dots');
    this.current = 0;
    this.timer = null;
  }
  init() {
    this.quotes.forEach((q, i) => {
      const dot = Dom.el('button', i === 0 ? 'on' : '');
      dot.setAttribute('aria-label', 'Frase ' + (i + 1));
      dot.addEventListener('click', () => { this.show(i); this.restart(); });
      this.dotsEl.appendChild(dot);
    });
    this.show(0);
    this.restart();
    if (!window.gsap) return;
    ScrollTrigger.create({
      trigger: '#quotes', start: 'top 70%',
      onEnter: () => this.restart(), onLeaveBack: () => this.stop()
    });
  }
  show(i) {
    this.current = i;
    const apply = () => {
      this.textEl.textContent = '«' + this.quotes[i] + '»';
      this.idxEl.textContent = (i + 1) + ' / ' + this.quotes.length + ' — Michelle Relayze';
      Dom.qsa('button', this.dotsEl).forEach((d, k) => d.classList.toggle('on', k === i));
    };
    if (!window.gsap) { apply(); return; }
    gsap.timeline()
      .to(this.textEl, { y: -24, autoAlpha: 0, duration: .45, ease: 'power2.in' })
      .add(apply)
      .fromTo(this.textEl, { y: 30, autoAlpha: 0 }, { y: 0, autoAlpha: 1, duration: .7, ease: Config.EASE_OUT });
  }
  restart() {
    this.stop();
    this.timer = setInterval(() => {
      this.show((this.current + 1) % this.quotes.length);
    }, 5200);
  }
  stop() { if (this.timer) clearInterval(this.timer); }
}

