/* ── 21 · APLICACIÓN (raíz de composición) ─────────────────────────────────── */
class App {
  constructor() {
    this.lightbox  = new Lightbox();
    this.renderers = [
      new TimelineRenderer('#timeline',       DataRepository.timeline),
      new TitlesRenderer('#titles-grid',      DataRepository.titles),
      new ContestantsRenderer('#contestants', DataRepository.contestants),
      new FilmsRenderer('#films',             DataRepository.films),
      new CareerRenderer('#career-grid',      DataRepository.career),
      new ActivismRenderer('#act-grid',       DataRepository.activism),
      new GalleryRenderer('#gallery-grid',    DataRepository.gallery, this.lightbox)
    ];
    this.hero     = new HeroSequence();
    this.marquee  = new Marquee();
    this.nav      = new Navigation();
    this.cursor   = new CursorFX();
    this.quotes   = new QuotesRotator();
    this.exporter = new GitHubExporter();
    this.reveal   = new RevealManager();
  }
  boot() {
    Dom.qs('#footer-year').textContent = new Date().getFullYear();
    this.hero.setImage();
    this.renderers.forEach((r) => r.build());
    this.marquee.init();
    this.nav.init();
    this.exporter.init();
    new Preloader(() => {
      this.hero.play();
      this.reveal.init();
      this.renderers.forEach((r) => r.animate());
      this.quotes.init();
      if (window.gsap) ScrollTrigger.refresh();
    }).run();
    window.addEventListener('load', () => {
      if (window.gsap) ScrollTrigger.refresh();
    });
  }
}

/* ── ARRANQUE ──────────────────────────────────────────────────────────────── */
window.addEventListener('DOMContentLoaded', () => new App().boot());
