.reglas .col{border:1px solid var(--linea);border-radius:10px;padding:24px 24px 20px;background:var(--papel-2)}
.reglas .col h3{font-family:var(--serif);font-size:1.35rem;margin-bottom:14px}
.reglas .col.no h3{color:var(--acento)}
.reglas .col.si h3{color:#2f6b4f}
.reglas ul{list-style:none}
.reglas li{padding:7px 0 7px 26px;position:relative;font-size:.94rem;color:var(--suave)}
.reglas .no li::before{content:'✕';position:absolute;left:0;color:var(--acento)}
.reglas .si li::before{content:'✓';position:absolute;left:0;color:#2f6b4f}
.tipo{margin-top:26px;background:var(--marca);border-left:3px solid var(--marca-linea);border-radius:0 8px 8px 0;padding:16px 20px;font-size:.92rem;color:#6b5413}
.tipo b{color:#4a3a10}

footer.lab{border-top:3px double var(--acento);padding-top:26px;font-size:.78rem;letter-spacing:.18em;text-transform:uppercase;color:var(--suave);display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap}
@media (max-width:760px){.reglas{grid-template-columns:1fr}}
</style>
</head>
<body>
<div class="wrap">

<header class="lab">
  <div class="kicker">Proyecto Angélica · Michelle Relayze</div>
  <h1>Laboratorio de portadas: <em>sin catálogo</em></h3>
  <p class="bajada">Michelle dijo que no quiere una portada de catálogo. Quiere algo puro, humano. Estos son los tres prompts que usaría —y el constructor para mezclarlos—, listos para pegar en cualquier generador de imágenes.</div>
  <div class="nota-servicio">Nota: el servicio de generación de imágenes está caído ahora mismo, así que cada concepto lleva un <b>boceto SVG</b> como vista previa. Los prompts de abajo están completos y listos: pégalos tal cual en el generador que uses y añade la tipografía después, en Figma o Canva.</div>
</header>

<!-- ═══ 1 · TRES CONCEPTOS ═════════════════════════════════════════════════ -->
<section>
  <h2 class="sec">1 · Tres conceptos, tres prompts</h2>
  <p class="lead">Los tres evitan el catálogo por el mismo sitio: quitan el personaje publicitario y dejan lo que el libro ya sabe contar — los tacones rojos de la madre, la mujer sin personaje, el espejo empañado.</p>

  <div class="conceptos">

    <!-- CONCEPTO A -->
    <article class="card">
      <div class="sketch" aria-label="Boceto: tacones rojos junto a una puerta">
        <svg viewBox="0 0 300 400" role="img">
          <rect width="300" height="400" fill="#e7dfcf"/>
          <polygon points="210,0 300,0 300,400 150,400" fill="#f2ead9" opacity=".8"/>
          <rect x="216" y="40" width="58" height="250" fill="#d9cfba"/>
          <rect x="222" y="46" width="46" height="238" fill="#cbbfa6"/>
          <circle cx="228" cy="170" r="3" fill="#8a7a5f"/>
          <rect x="0" y="290" width="300" height="110" fill="#cbb694"/>
          <line x1="0" y1="312" x2="300" y2="312" stroke="#b39c78" stroke-width="1"/>
          <line x1="0" y1="342" x2="300" y2="342" stroke="#b39c78" stroke-width="1"/>
          <ellipse cx="118" cy="330" rx="66" ry="10" fill="#a8906c" opacity=".5"/>
          <path d="M92 322 q4 -26 14 -30 q10 -4 12 8 q2 12 10 16 q10 5 22 6 q10 1 10 6 l0 4 l-56 0 z" fill="#8f1f2b"/>
          <path d="M128 322 q4 -26 14 -30 q10 -4 12 8 q2 12 10 16 q10 5 22 6 q10 1 10 6 l0 4 l-56 0 z" fill="#a32633"/>
          <path d="M96 296 q6 -10 10 -8" stroke="#6d1620" stroke-width="2" fill="none"/>
          <path d="M132 296 q6 -10 10 -8" stroke="#7d1c26" stroke-width="2" fill="none"/>
        </svg>
      </div>
      <div class="body">
        <h3><span>A ·</span> Los tacones rojos</h3>
        <p class="idea">Sin rostro. El símbolo central del manuscrito —los tacones rojos de la madre— puesto en el suelo de una casa, con luz de mañana. La portada más pura: nadie posa, pero alguien estuvo ahí.</p>
        <div class="prompts">
          <pre id="pA-es"></pre>
          <pre id="pA-en"></pre>
          <div class="fila-btn">
            <button class="btn mini" data-copy="#pA-es">Copiar ES</button>
            <button class="btn mini" data-copy="#pA-en">Copiar EN</button>
          </div>
        </div>
      </div>
    </article>

    <!-- CONCEPTO B -->
    <article class="card">
      <div class="sketch" aria-label="Boceto: mujer sentada junto a una ventana, sin posa">
        <svg viewBox="0 0 300 400" role="img">
          <rect width="300" height="400" fill="#e7dfcf"/>
          <rect x="180" y="30" width="90" height="180" fill="#f6efdd"/>
          <line x1="225" y1="30" x2="225" y2="210" stroke="#cbbfa6" stroke-width="3"/>
          <line x1="180" y1="120" x2="270" y2="120" stroke="#cbbfa6" stroke-width="3"/>
          <polygon points="180,210 270,210 240,400 120,400" fill="#f2ead9" opacity=".7"/>
          <circle cx="118" cy="150" r="30" fill="#d9b98f"/>
          <path d="M88 150 q-6 60 6 92 q4 12 24 12 q22 0 26 -12 q10 -34 4 -92 q-4 -22 -30 -22 q-26 0 -30 20z" fill="#c8a06a"/>
          <path d="M84 190 q-16 60 -6 130 q2 20 40 20 q40 0 42 -20 q8 -70 -8 -130z" fill="#efe6d4"/>
          <path d="M104 262 q14 14 30 0 q6 10 -2 16 q-14 8 -26 0 q-8 -6 -2 -16z" fill="#e0d5bf"/>
          <ellipse cx="118" cy="268" rx="12" ry="9" fill="#b98d5e"/>
        </svg>
      </div>
      <div class="body">
        <h3><span>B ·</span> La mujer sin personaje</h3>
        <p class="idea">Michelle sin corona, sin vestido, sin maquillaje de estudio: suéter de lana, café entre las manos, riéndose fuera de cuadro. La cara de siempre, sin el personaje encima.</p>
        <div class="prompts">
          <pre id="pB-es"></pre>
          <pre id="pB-en"></pre>
          <div class="fila-btn">
            <button class="btn mini" data-copy="#pB-es">Copiar ES</button>
            <button class="btn mini" data-copy="#pB-en">Copiar EN</button>
          </div>
        </div>
      </div>
    </article>

    <!-- CONCEPTO C -->
    <article class="card">
      <div class="sketch" aria-label="Boceto: espejo empañado con corona dibujada con el dedo">
        <svg viewBox="0 0 300 400" role="img">
          <rect width="300" height="400" fill="#e7dfcf"/>
          <rect x="70" y="40" width="160" height="300" rx="14" fill="#8a7a5f"/>
          <rect x="80" y="50" width="140" height="280" rx="10" fill="#d8d2c4"/>
          <rect x="80" y="50" width="140" height="280" rx="10" fill="#e9e4d8" opacity=".75"/>
          <path d="M120 150 l14 -22 l12 16 l12 -20 l12 20 l12 -16 l14 22 l-6 14 l-66 0 z" fill="none" stroke="#b7ae9c" stroke-width="4" stroke-linejoin="round" opacity=".9"/>
          <ellipse cx="150" cy="250" rx="34" ry="52" fill="#cfc7b6" opacity=".8"/>
          <ellipse cx="150" cy="212" rx="15" ry="18" fill="#cfc7b6" opacity=".8"/>
          <path d="M92 70 q30 18 8 44" stroke="#f4efe3" stroke-width="6" fill="none" opacity=".7"/>
        </svg>
      </div>
      <div class="body">
        <h3><span>C ·</span> El espejo empañado</h3>
        <p class="idea">Un espejo con vaho y una corona torcida dibujada con un dedo; detrás, apenas, una silueta que se aleja. Identidad sin rostro: la portada que dice «siempre fui ella» sin explicarlo.</p>
        <div class="prompts">
          <pre id="pC-es"></pre>
          <pre id="pC-en"></pre>
          <div class="fila-btn">
            <button class="btn mini" data-copy="#pC-es">Copiar ES</button>
            <button class="btn mini" data-copy="#pC-en">Copiar EN</button>
          </div>
        </div>
      </div>
    </article>

  </div>
</section>

<hr class="regla">

<!-- ═══ 2 · CONSTRUCTOR ════════════════════════════════════════════════════ -->
<section>
  <h2 class="sec">2 · Constructor de prompt</h2>
  <p class="lead">Mezcla concepto, luz, textura y texto. El cierre anti-católogo va siempre incluido: es la parte que Michelle pidió.</p>
  <div class="builder">
    <div class="grid">
      <div class="campo"><label for="sel-concepto">Concepto</label>
        <select id="sel-concepto">
          <option value="A">A · Los tacones rojos (sin rostro)</option>
          <option value="B">B · La mujer sin personaje</option>
          <option value="C">C · El espejo empañado</option>
        </select>
      </div>
      <div class="campo"><label for="sel-luz">Luz</label>
        <select id="sel-luz">
          <option value="manana">Mañana, ventana fuera de cuadro</option>
          <option value="dorada">Hora dorada, rasante</option>
          <option value="invierno">Invierno blanco, muy difusa</option>
        </select>
      </div>
      <div class="campo"><label for="sel-textura">Textura</label>
        <select id="sel-textura">
          <option value="g35">Grano de 35 mm</option>
          <option value="medio">Papel mate de formato medio</option>
          <option value="ninguna">Limpia, sin grano</option>
        </select>
      </div>
      <div class="campo"><label for="sel-texto">Texto en imagen</label>
        <select id="sel-texto">
          <option value="none">Sin texto (tipografía después)</option>
          <option value="titulo">Título + nombre de autora</option>
          <option value="solo">Solo título</option>
        </select>
      </div>
    </div>
    <pre id="out-es"></pre>
    <pre id="out-en"></pre>
    <div class="fila-btn">
      <button class="btn" data-copy="#out-es">Copiar prompt ES</button>
      <button class="btn" data-copy="#out-en">Copiar prompt EN</button>
    </div>
  </div>
</section>

<hr class="regla">

<!-- ═══ 3 · REGLAS ANTI-CATÁLOGO ════════════════════════════════════════════ -->
<section>
  <h2 class="sec">3 · Reglas de la portada que ella quiere</h2>
  <p class="lead">Lo que separa una portada de catálogo de una portada humana no es la cámara: es lo que se prohíbe y lo que se busca.</p>
  <div class="reglas">
    <div class="col no">
      <h3>Prohibido</h3>
      <ul>
        <li>Corona, banda, vestido de noche.</li>
        <li>Luz de estudio, brillo publicitario, retoque de piel.</li>
        <li>Posa frontal de catálogo, mirada «vendida».</li>
        <li>Fondo neutro de estudio o degradado de cartel.</li>
        <li>Tipografía dorada con sombra o efecto metal.</li>
        <li>La palabra «reina» como adorno gráfico.</li>
      </ul>
    </div>
    <div class="col si">
      <h3>Buscado</h3>
      <ul>
        <li>Un objeto que cuente: tacones rojos, café, espejo.</li>
        <li>Luz natural que entre por una ventana, no por un flash.</li>
        <li>Piel verdadera: pecas, textura, manos reales.</li>
        <li>Espacio negativo amplio: silencio visual.</li>
        <li>Grano de película: memoria, no publicidad.</li>
        <li>Que al verla se pueda <em>oír</em> su voz, no su personaje.</li>
      </ul>
    </div>
  </div>
  <div class="tipo">
    <b>Tipografía (se añade después, nunca dentro del generador):</b> Cormorant Garamond, versalitas con tracking amplio (.18em) para el título «EL ÍNTIMO DE UNA MUJER» arriba; «MICHELLE RELAYZE» abajo, en Jost 400 con .4em. Sin oro con relieve: si se quiere un acento, un solo asterisco ✦ en granate, pequeño, entre título y autora.
  </div>
</section>

<footer class="lab">
  <span>Proyecto Angélica · documento de trabajo interno</span>
  <span>Hecho con hechos verificados · sin ficción no autorizada</span>
</footer>

</div>

<script>
/* ════════════════════════════════════════════════════════════════════════════
   LABORATORIO DE PORTADAS — lógica OOP
   · PromptFragments: datos puros (fragmentos ES/EN).
   · PromptBuilder: compone el prompt final (composición + estrategia).
   · CopyController: portapapeles con fallback (responsabilidad única).
   ════════════════════════════════════════════════════════════════════════════ */
'use strict';

class PromptFragments {
  static get conceptos() {
    return {
      A: {
        es: 'Portada de libro memorial, vertical 2:3. Escena vacía sin personas: un par de tacones rojos de charol, gastados pero cuidados, colocados juntos sobre un suelo de madera desgastada junto a una puerta entreabierta',
        en: 'Literary memoir book cover, vertical 2:3. Empty scene, no people: a pair of worn red patent-leather high heels placed neatly together on a scratched wooden floor beside a half-open door'
      },
      B: {
        es: 'Retrato íntimo y desposeído, vertical 2:3. Mujer latina de unos cuarenta y tantos años, cabello largo ondulado color miel, sentada junto a una ventana; suéter de lana crema, sin maquillaje aparente, pecas y textura real de la piel; ríe suave mirando fuera de cuadro, con una taza de café entre las manos; sin posa, estilo documental',
        en: 'Intimate unposed documentary portrait, vertical 2:3. Latina woman in her mid-forties with long wavy honey-blonde hair sitting by a window; cream knit sweater, no visible makeup, real skin texture and freckles; laughing softly looking off-camera, holding a coffee cup with both hands; candid, documentary style'
      },
      C: {
        es: 'Espejo antiguo de marco de madera oscura cubierto de vaho; con un dedo se ha dibujado una pequeña corona torcida en el vaho; detrás del cristal, borrosa y apenas visible, la silueta de una mujer de espaldas que se aleja; luz suave de dormitorio',
        en: 'Old dark-wood mirror covered in bathroom steam; a small crooked crown drawn with a fingertip into the fogged glass; behind the glass, blurred and barely visible, the silhouette of a woman seen from behind walking away; soft bedroom light'
      }
    };
  }
  static get luces() {
    return {
      manana: { es: 'luz de mañana entrando por una ventana fuera de cuadro, con motas de polvo en el haz', en: 'soft morning light from an off-frame window, dust motes floating in the beam' },
      dorada: { es: 'luz dorada baja de atardecer, cálida y rasante', en: 'low golden-hour light, warm and raking' },
      invierno:{ es: 'luz blanca y fría de invierno, muy difusa', en: 'cold, very diffuse winter light' }
    };
  }
  static get texturas() {
    return {
      g35:     { es: 'grano de película de 35 mm, profundidad de campo corta', en: '35mm film grain, shallow depth of field' },
      medio:   { es: 'textura de papel fotográfico mate de formato medio, colores apagados', en: 'matte medium-format photographic paper texture, muted colors' },
      ninguna: { es: 'acabado limpio y sutil, sin grano evidente', en: 'clean subtle finish, no visible grain' }
    };
  }
  static get textos() {
    return {
      none:   { es: 'Sin texto, sin tipografía, sin letras: deja espacio negativo amplio en la parte superior para el titular.', en: 'No text, no typography, no letters: leave large negative space at the top for the title.' },
      titulo: { es: 'Con tipografía serif discreta: arriba el título «EL ÍNTIMO DE UNA MUJER» en versalitas con tracking amplio, y abajo «MICHELLE RELAYZE».', en: "With discreet serif typography: title 'EL ÍNTIMO DE UNA MUJER' in letter-spaced small caps at top, and 'MICHELLE RELAYZE' at bottom." },
      solo:   { es: 'Solo el título «EL ÍNTIMO DE UNA MUJER» arriba, en versalitas serif; sin nombre de autora.', en: "Only the title 'EL ÍNTIMO DE UNA MUJER' at top in serif small caps; no author name." }
    };
  }
  static get cierre() {
    return {
      es: 'Prohibido: corona, vestido de noche, brillo de estudio, posa de catálogo, fondo publicitario. Buscado: ternura, silencio, memoria, piel verdadera.',
      en: 'Forbidden: crown, evening gown, studio gloss, catalog pose, advertising backdrop. Wanted: tenderness, silence, memory, real skin.'
    };
  }
}

class PromptBuilder {
  constructor(selIds, outIds) {
    this.sel = {
      concepto: document.getElementById(selIds.concepto),
      luz:      document.getElementById(selIds.luz),
      textura:  document.getElementById(selIds.textura),
      texto:    document.getElementById(selIds.texto)
    };
    this.out = {
      es: document.getElementById(outIds.es),
      en: document.getElementById(outIds.en)
    };
  }
  compose(lang) {
    const F = PromptFragments;
    const c = F.conceptos[this.sel.concepto.value][lang];
    const l = F.luces[this.sel.luz.value][lang];
    const t = F.texturas[this.sel.textura.value][lang];
    const x = F.textos[this.sel.texto.value][lang];
    const z = F.cierre[lang];
    return c + '; ' + l + '; ' + t + '. ' + x + ' ' + z;
  }
  render() {
    this.out.es.innerHTML = '<span class="lang">Prompt · Español</span>' + this.compose('es');
    this.out.en.innerHTML = '<span class="lang">Prompt · English</span>' + this.compose('en');
  }
  bind() {
    Object.values(this.sel).forEach((s) => s.addEventListener('change', () => this.render()));
    this.render();
  }
}

class CopyController {
  constructor() { this.buttons = Array.from(document.querySelectorAll('[data-copy]')); }
  init() { this.buttons.forEach((b) => b.addEventListener('click', () => this.copy(b))); }
  copy(btn) {
    const target = document.querySelector(btn.getAttribute('data-copy'));
    if (!target) return;
    const text = target.innerText.replace(/^Prompt · (Español|English)/, '').trim();
    const done = () => {
      const old = btn.textContent;
      btn.textContent = '✓ Copiado';
      setTimeout(() => { btn.textContent = old; }, 1500);
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(done);
    } else {
      const ta = document.createElement('textarea');
      ta.value = text; document.body.appendChild(ta);
      ta.select(); document.execCommand('copy'); ta.remove(); done();
    }
  }
}

class PortadaLab {
  constructor() {
    this.builder = new PromptBuilder(
      { concepto:'sel-concepto', luz:'sel-luz', textura:'sel-textura', texto:'sel-texto' },
      { es:'out-es', en:'out-en' }
    );
    this.copias = new CopyController();
  }
  seedCards() {
    const F = PromptFragments;
    const base = (k, lang) => {
      const c = F.conceptos[k][lang];
      const l = F.luces.manana[lang];
      const t = F.texturas.g35[lang];
      const x = F.textos.none[lang];
      const z = F.cierre[lang];
      return '<span class="lang">Prompt · ' + (lang === 'es' ? 'Español' : 'English') + '</span>' +
             c + '; ' + l + '; ' + t + '. ' + x + ' ' + z;
    };
    ['A','B','C'].forEach((k) => {
      document.getElementById('p' + k + '-es').innerHTML = base(k, 'es');
      document.getElementById('p' + k + '-en').innerHTML = base(k, 'en');
    });
  }
  init() {
    this.seedCards();
    this.builder.bind();
    this.copias.init();
  }
}

document.addEventListener('DOMContentLoaded', () => new PortadaLab().init());
</script>
</body>
</html>
